method correct_bracketing(brackets: string) returns (result: bool)
    requires brackets != null
    ensures result == (forall i :: 0 <= i < |brackets| ==> (countOpen(brackets, i) == countClose(brackets, i)))

    // Helper function to count the number of opening brackets '(' up to index i
    function countOpen(brackets: string, i: int): int
        requires 0 <= i <= |brackets|
        ensures 0 <= countOpen(brackets, i) <= i
    {
        var count := 0;
        var j := 0;
        while j < i
            invariant 0 <= j <= i
            invariant count == countOpen(brackets, j)
        {
            if brackets[j] == '(' {
                count := count + 1;
            }
            j := j + 1;
        }
        return count;
    }

    // Helper function to count the number of closing brackets ')' up to index i
    function countClose(brackets: string, i: int): int
        requires 0 <= i <= |brackets|
        ensures 0 <= countClose(brackets, i) <= i
    {
        var count := 0;
        var j := 0;
        while j < i
            invariant 0 <= j <= i
            invariant count == countClose(brackets, j)
        {
            if brackets[j] == ')' {
                count := count + 1;
            }
            j := j + 1;
        }
        return count;
    }
